using sv_490f1278abd443af8a2f5caabf529074.Models;

namespace sv_490f1278abd443af8a2f5caabf529074.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000);
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300);
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_490f1278abd443af8a2f5caabf529074.Components.Pages.Apply

<nav class="step-indicator mb-4" aria-label="Application steps">
    <ol class="d-flex list-unstyled justify-content-between position-relative px-0">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var status = GetStepStatus(step);
            <li class="step-item text-center flex-fill @status" @key="step">
                @if (status == "completed")
                {
                    <button class="btn btn-link p-0 text-decoration-none w-100" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <span class="step-label d-block small mt-1 text-success fw-semibold">@StepNames[step]</span>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(status == "active" ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@(step + 1)</span>
                        <span class="step-label d-block small mt-1 @(status == "active" ? "fw-semibold text-primary" : "text-muted")">@StepNames[step]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step < CurrentStep) return "completed";
        if (step == CurrentStep) return "active";
        return "future";
    }
}

.step-indicator ol {
    counter-reset: step;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    font-weight: 600;
    font-size: 0.9rem;
}

.step-item {
    position: relative;
}

.step-item + .step-item::before {
    content: "";
    position: absolute;
    top: 1.1rem;
    left: -50%;
    width: 100%;
    height: 2px;
    background-color: #dee2e6;
    z-index: -1;
}

.step-item.completed + .step-item::before {
    background-color: #198754;
}

@using sv_490f1278abd443af8a2f5caabf529074.Models
@namespace sv_490f1278abd443af8a2f5caabf529074.Components.Pages.Apply

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @ReferenceNumber</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Reference.Name" @bind:event="oninput" placeholder="Reference name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Reference.Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="Reference.Email" @bind:event="oninput" placeholder="email@example.com" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="Reference.Phone" @bind:event="oninput" placeholder="Phone number" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int ReferenceNumber { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@using sv_490f1278abd443af8a2f5caabf529074.Models
@namespace sv_490f1278abd443af8a2f5caabf529074.Components.Pages.Apply

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input class="form-control" @bind="Model.FullName" @bind:event="oninput" placeholder="John Doe" />
    </div>
